//! A project's `build.java`: compiled, linked against the script platform, and run over project
//! storage.
//!
//! A script only sees typed project-relative storage, through the `Project`, `Output`, `Tasks`,
//! and `Build` classes of the `jals.build` package. It runs against one immutable [`ProjectView`];
//! generated bytes and build directives stay buffered until a successful run is committed in one
//! revision-checked transaction.

use alloc::borrow::ToOwned;
use alloc::collections::{BTreeMap, BTreeSet};
use alloc::format;
use alloc::string::{String, ToString};
use alloc::vec::Vec;
use core::error::Error as CoreError;
use core::fmt;
use core::ops::Range;

use jals_config::Manifest;
use jals_storage::{
    ArtifactCache, CacheBackend, CacheKey, CacheNamespace, ContentDigest, FileKey, ProjectView,
    ProvenanceFold, Revision,
};
use serde::{Deserialize, Serialize};

use crate::task::{TaskPlan, TaskPlanLimits};

// Bumped for the limit surface: the AST bounds (`max_variables`, `max_functions`, and the three
// recursion depths) are gone from `BuildScriptLimits`, and the persisted state wire lost their
// fields — a state written before them cannot decode at all. The plan format is unchanged, so only
// the state version moves.
//
// Bumped for the Java task surface: `build.java` scripts gained `jals.build.Tasks` — the whole
// declarative vocabulary, down to the mapping grammars — and the builder now hands the finished
// plan over rather than unwrapping it. The plan's own format is unchanged, so only the API version
// moves.
//
// Both bumped for declarative remap: `TaskNodeKind` gained `ProjectText`, and `RemapJar` gained
// required `format` / `direction` / `hierarchy` fields. The plan is `deny_unknown_fields` and is
// fingerprinted as canonical JSON, so a pre-remap state decodes to a different plan than it was
// written from — the API bump reseeds the cache key so one is never fetched and decoded at all.
//
// Bumped before that for publication intent: `Tasks.publishTree` gained a required intent argument
// (API), and `TaskTerminal::PublishTree` gained a required `intent` field (state).
//
// And before that for build features: scripts gained `Build.feature`/`Build.features`, and
// `FingerprintInputsWire` gained a required `features` field.
// And before that for the Java engine: a script's engine is selected by the manifest tag, and a
// `java` script's host surface is the `jals.build` package. The API version is what reseeds a
// cache written by the engine's predecessor.
const BUILD_SCRIPT_API_VERSION: u32 = 9;
const BUILD_SCRIPT_STATE_VERSION: u32 = 8;
const BUILD_ARTIFACT_ROOT: &str = "target/jals/build";
/// Everything `jals` owns under the project: build artifacts, the verified cache, acquired
/// dependencies. All of it is derived, so none of it is an input to a script's fingerprint.
const MANAGED_ROOT: &str = "target/jals";
const MANIFEST_FILE: &str = "jals.toml";

/// Directory under `target/jals/build/script` where script-generated files are published.
pub const BUILD_SCRIPT_OUTPUT_ROOT: &str = "target/jals/build/script/out";

/// Cache identity for one build-script project.
///
/// Dependency projects must use a scope derived from their stable content identity. The root
/// project uses [`ROOT`](Self::ROOT). Scope values are opaque so callers cannot accidentally depend
/// on their cache encoding.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct BuildScriptCacheScope(Option<ContentDigest>);

impl BuildScriptCacheScope {
    /// Distinguished cache scope for the root project executed by `execute_build_script`.
    pub const ROOT: Self = Self(None);

    /// Construct an isolated dependency-project cache scope from a stable digest.
    pub const fn new(digest: ContentDigest) -> Self {
        Self(Some(digest))
    }

    const fn digest(self) -> Option<ContentDigest> {
        self.0
    }
}

/// Resource limits applied to compilation, evaluation, and generated output.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BuildScriptLimits {
    /// Maximum build-script source bytes accepted before compilation.
    pub max_script_size: usize,
    /// Maximum script operations in one execution.
    pub max_operations: u64,
    /// Maximum string length in bytes.
    pub max_string_size: usize,
    /// Maximum array length.
    pub max_array_size: usize,
    /// Maximum map size and maximum size of each host-side directive map.
    pub max_map_size: usize,
    /// Maximum bytes in any path supplied by the script.
    pub max_path_bytes: usize,
    /// Maximum segments in any path supplied by the script.
    pub max_path_depth: usize,
    /// Maximum combined bytes in arguments, script diagnostics, metadata, and phase environments.
    pub max_host_directive_bytes: usize,
    /// Maximum number of distinct files generated by one execution.
    pub max_output_files: usize,
    /// Maximum bytes in one generated file.
    pub max_output_file_size: usize,
    /// Maximum combined bytes in all generated files.
    pub max_total_output_size: usize,
    /// Maximum serialized bytes materialized for one persistent build-script state record.
    pub max_cache_state_size: usize,
    /// Maximum value-producing nodes in one declarative task graph.
    pub max_tasks: usize,
    /// Maximum dependency edges, including terminal inputs, in one task graph.
    pub max_task_edges: usize,
    /// Maximum combined bytes in task literals.
    pub max_task_literal_bytes: usize,
    /// Maximum side-effecting terminals in one task graph.
    pub max_task_terminals: usize,
    /// Maximum physical source-tree publication terminals in one task graph.
    pub max_publication_roots: usize,
    /// Ceiling on any single build-task fetch, including a size projected out of fetched JSON.
    pub max_fetch_bytes: u64,
}

impl Default for BuildScriptLimits {
    fn default() -> Self {
        Self {
            max_script_size: 1_048_576,
            max_operations: 1_000_000,
            max_string_size: 1_048_576,
            max_array_size: 65_536,
            max_map_size: 4_096,
            max_path_bytes: 4_096,
            max_path_depth: 128,
            max_host_directive_bytes: 1_048_576,
            max_output_files: 256,
            max_output_file_size: 4 * 1_048_576,
            max_total_output_size: 16 * 1_048_576,
            max_cache_state_size: 4 * 1_048_576,
            max_tasks: 4_096,
            max_task_edges: 16_384,
            max_task_literal_bytes: 1_048_576,
            max_task_terminals: 256,
            max_publication_roots: 32,
            // Comfortably above a Minecraft client/server jar, far below "exhaust the machine".
            max_fetch_bytes: 1_024 * 1_048_576,
        }
    }
}

impl BuildScriptLimits {
    fn validate(&self) -> Result<(), BuildScriptError> {
        let limits = [
            (self.max_script_size != 0, "max_script_size"),
            (self.max_operations != 0, "max_operations"),
            (self.max_string_size != 0, "max_string_size"),
            (self.max_array_size != 0, "max_array_size"),
            (self.max_map_size != 0, "max_map_size"),
            (self.max_path_bytes != 0, "max_path_bytes"),
            (self.max_path_depth != 0, "max_path_depth"),
            (
                self.max_host_directive_bytes != 0,
                "max_host_directive_bytes",
            ),
            (self.max_output_files != 0, "max_output_files"),
            (self.max_output_file_size != 0, "max_output_file_size"),
            (self.max_total_output_size != 0, "max_total_output_size"),
            (self.max_cache_state_size != 0, "max_cache_state_size"),
            (self.max_tasks != 0, "max_tasks"),
            (self.max_task_edges != 0, "max_task_edges"),
            (self.max_task_literal_bytes != 0, "max_task_literal_bytes"),
            (self.max_task_terminals != 0, "max_task_terminals"),
            (self.max_publication_roots != 0, "max_publication_roots"),
            (self.max_fetch_bytes != 0, "max_fetch_bytes"),
        ];
        if let Some((_, name)) = limits.into_iter().find(|(valid, _)| !valid) {
            return Err(BuildScriptError::InvalidLimit(name));
        }

        Ok(())
    }

    const fn task_plan_limits(&self) -> TaskPlanLimits {
        TaskPlanLimits {
            max_tasks: self.max_tasks,
            max_edges: self.max_task_edges,
            max_literal_bytes: self.max_task_literal_bytes,
            max_terminals: self.max_task_terminals,
            max_publication_roots: self.max_publication_roots,
            max_fetch_bytes: self.max_fetch_bytes,
            max_path_bytes: self.max_path_bytes,
            max_path_depth: self.max_path_depth,
        }
    }
}

/// Explicit environment visible to `build.env`.
///
/// Nothing is inherited from the host process. The ordered map makes the input suitable for a
/// future deterministic fingerprint without changing this API.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct BuildScriptEnvironment {
    values: BTreeMap<String, String>,
    /// Resolved Cargo-style build features, queried by `build.feature("…")`.
    ///
    /// Scoped to **one project**, like Cargo: for the root project these are its own `[features]`
    /// resolved against the command-line selection, and for a dependency they are what the
    /// `[dependencies]` entries pointing at it asked for — their `features` lists plus whatever
    /// those projects' `[features]` forwarded as `<dependency>/<feature>` — closed over the
    /// dependency's own `[features]`. Never the declaring project's own set, and never a
    /// `<dependency>/<feature>` directive, which is routed rather than enabled.
    /// [`Self::for_project`] is where the swap happens. Never inherited from the host process: they
    /// are not secrets and are authoritative, so they bypass the [`Self::HOST_PREFIX`] opt-in that
    /// guards `values`. Always folded into the build-script fingerprint so a changed selection
    /// rebuilds even though the script never declared it as an input.
    features: BTreeSet<String>,
}

impl BuildScriptEnvironment {
    /// The one prefix a host process may forward into a build script.
    ///
    /// A host environment carries credentials (`GITHUB_TOKEN`, `AWS_SECRET_ACCESS_KEY`, npm and
    /// cargo registry tokens, …), and a script that reads a value can forward it straight into a
    /// task fetch URL. Inheriting the whole environment would therefore hand every host secret to
    /// an untrusted `build.java` — including a dependency's, which the user never reviewed.
    /// Passing host state stays possible, but only through names the user opted in by choosing
    /// this prefix.
    const HOST_PREFIX: &'static str = "JALS_";

    /// Construct an empty environment.
    pub const fn new() -> Self {
        Self {
            values: BTreeMap::new(),
            features: BTreeSet::new(),
        }
    }

    /// Build an environment from a host process's variables, keeping only the opt-in
    /// [`Self::HOST_PREFIX`] names.
    ///
    /// This is the only supported way to cross the host boundary; see [`Self::HOST_PREFIX`] for
    /// why the rest of the environment stays out.
    pub fn from_host<I, K, V>(variables: I) -> Self
    where
        I: IntoIterator<Item = (K, V)>,
        K: Into<String>,
        V: Into<String>,
    {
        variables
            .into_iter()
            .map(|(name, value)| (name.into(), value.into()))
            .filter(|(name, _)| name.starts_with(Self::HOST_PREFIX))
            .collect()
    }

    /// Derive the environment for one project, replacing host-specific project metadata and
    /// installing that project's own build `features`.
    ///
    /// Features are per package, so they are a *required* argument rather than something carried
    /// over: the caller must say which set this project gets, and the previous project's set never
    /// leaks across the boundary. A dependency's set is resolved from the `[dependencies]` entries
    /// aimed at it, which is unrelated to whatever the declaring project selected for itself.
    #[must_use]
    pub fn for_project(&self, manifest: &Manifest, features: BTreeSet<String>) -> Self {
        const RESERVED: [&str; 4] = [
            "OUT_DIR",
            "JALS_MANIFEST_DIR",
            "JALS_PACKAGE_NAME",
            "JALS_PACKAGE_VERSION",
        ];

        let mut environment = Self {
            values: self
                .iter()
                .filter(|(name, _)| !RESERVED.contains(name))
                .map(|(name, value)| (name.to_owned(), value.to_owned()))
                .collect(),
            // Named here rather than patched in afterwards so that forgetting the caller's set is a
            // compile error, not a silently empty feature set.
            features,
        };
        environment.insert("OUT_DIR", BUILD_SCRIPT_OUTPUT_ROOT);
        environment.insert("JALS_MANIFEST_DIR", ".");
        if let Some(name) = &manifest.package.name {
            environment.insert("JALS_PACKAGE_NAME", name);
        }
        if let Some(version) = &manifest.package.version {
            environment.insert("JALS_PACKAGE_VERSION", version);
        }
        environment
    }

    /// Insert an explicit variable, returning its previous value.
    pub fn insert(&mut self, name: impl Into<String>, value: impl Into<String>) -> Option<String> {
        self.values.insert(name.into(), value.into())
    }

    /// Get an explicit variable.
    fn get(&self, name: &str) -> Option<&str> {
        self.values.get(name).map(String::as_str)
    }

    /// Iterate variables in lexical order.
    fn iter(&self) -> impl ExactSizeIterator<Item = (&str, &str)> {
        self.values
            .iter()
            .map(|(name, value)| (name.as_str(), value.as_str()))
    }

    /// Number of explicit variables.
    fn len(&self) -> usize {
        self.values.len()
    }

    /// This environment with the current project's resolved build features set to `features`.
    ///
    /// [`Self::for_project`] is the usual installer; this is for building an environment that is
    /// already scoped to one project.
    #[must_use]
    pub fn with_features(mut self, features: BTreeSet<String>) -> Self {
        self.features = features;
        self
    }

    /// Whether build feature `name` is enabled (backs `build.feature("…")`).
    fn has_feature(&self, name: &str) -> bool {
        self.features.contains(name)
    }

    /// Iterate the enabled build features in lexical order (backs `build.features()`).
    fn features(&self) -> impl ExactSizeIterator<Item = &str> {
        self.features.iter().map(String::as_str)
    }
}

impl FromIterator<(String, String)> for BuildScriptEnvironment {
    fn from_iter<T: IntoIterator<Item = (String, String)>>(iter: T) -> Self {
        Self {
            values: iter.into_iter().collect(),
            features: BTreeSet::new(),
        }
    }
}

/// How severe one script-reported diagnostic is.
///
/// Deliberately crate-private. Every consumer of a [`BuildScriptDiagnostic`] either needs the
/// whole rendering ([`fmt::Display`]) or a two-way answer ([`BuildScriptDiagnostic::is_error`]);
/// none needs to name a severity. Publishing this enum together with its `Display` would hand
/// every host the two halves of `format!("{severity}: {message}")`, which is the rendering that
/// belongs here. When a third severity arrives, `is_error` stops answering the question at the
/// sites that matter and the compiler says so — that is when this becomes public.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum BuildScriptSeverity {
    Warning,
    Error,
}

impl fmt::Display for BuildScriptSeverity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Warning => "warning",
            Self::Error => "error",
        })
    }
}

/// One script-reported diagnostic: a severity and the message the script passed.
///
/// The fields are sealed so the severity cannot be recovered by matching. A consumer either
/// renders the whole diagnostic or asks [`is_error`](Self::is_error); it never spells the severity
/// itself.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BuildScriptDiagnostic {
    severity: BuildScriptSeverity,
    message: String,
}

impl BuildScriptDiagnostic {
    /// A non-fatal diagnostic.
    pub fn warning(message: impl Into<String>) -> Self {
        Self {
            severity: BuildScriptSeverity::Warning,
            message: message.into(),
        }
    }

    /// A fatal diagnostic. Any such diagnostic prevents publication.
    pub fn error(message: impl Into<String>) -> Self {
        Self {
            severity: BuildScriptSeverity::Error,
            message: message.into(),
        }
    }

    /// Diagnostic message without its severity.
    ///
    /// For a destination that carries severity in a channel of its own — an LSP
    /// `DiagnosticSeverity`, a Monaco marker, the `warning:` lead of a CLI line. A destination
    /// that is a plain string renders the whole diagnostic through [`fmt::Display`] instead.
    pub fn message(&self) -> &str {
        &self.message
    }

    /// Whether this diagnostic prevents publication.
    pub const fn is_error(&self) -> bool {
        matches!(self.severity, BuildScriptSeverity::Error)
    }
}

/// `<severity>: <message>` — what a host prints.
///
/// This rendering lives here rather than in each host for the reason `jals_classpath::Warning`'s
/// does: a message alone is not the diagnostic. A script's
/// `build.warning` and its `build.error` read identically once the severity is dropped, so a host
/// that prints [`message`](Self::message) into a plain string either restates a severity it
/// re-derived or silently presents a warning as an error.
impl fmt::Display for BuildScriptDiagnostic {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.severity, self.message)
    }
}

/// Deterministic result of one successfully published build-script execution.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BuildScriptOutput {
    /// Storage revision containing the published files. It is unchanged for an exact no-op.
    revision: Revision,
    /// Every file written below [`BUILD_SCRIPT_OUTPUT_ROOT`], in key order.
    pub generated_files: BTreeSet<FileKey>,
    /// Generated or project source files added by the script, in key order.
    pub generated_sources: BTreeSet<FileKey>,
    /// Additional project classpath entries, in key order.
    pub additional_classpath: BTreeSet<FileKey>,
    /// Extra `javac` arguments in script call order.
    pub javac_args: Vec<String>,
    /// Extra JVM arguments in script call order.
    pub jvm_args: Vec<String>,
    /// Explicit environment for compilation.
    pub compile_env: BTreeMap<String, String>,
    /// Explicit environment for execution.
    pub run_env: BTreeMap<String, String>,
    /// Project files that invalidate this result, in key order.
    pub rerun_files: BTreeSet<FileKey>,
    /// Environment names that invalidate this result, in lexical order.
    rerun_env: BTreeSet<String>,
    /// Script warnings and any non-fatal cache-persistence warning.
    ///
    /// Successful results never contain an error diagnostic: a run that produced one diverts the
    /// whole collection into [`BuildScriptError::ReportedErrors`] before an output exists. That is
    /// a structural guarantee rather than a filter, so a host promoting these into a warning
    /// channel of its own needs no severity test — and a host that writes one is describing a
    /// state that cannot arise while erasing the one that would.
    pub diagnostics: Vec<BuildScriptDiagnostic>,
    /// Script metadata, in lexical key order.
    metadata: BTreeMap<String, String>,
    /// Declarative host tasks recorded by the script.
    pub task_plan: TaskPlan,
}

/// Canonical output-root-relative path returned by `output.write` and `output.write_text`.
///
/// Scripts pass this value directly to `build.add_source` or `build.add_classpath`. Hosts can use
/// [`key`](Self::key) to access the fully rooted storage identity.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct BuildScriptOutputPath {
    key: FileKey,
}

/// Aggregate-local knowledge used to reconcile stale generated files safely.
///
/// Durable ownership is recovered from the project artifact cache when possible. A stale file is
/// removed only when its current bytes still match verified bytes known to this session; unknown
/// or externally modified files are never deleted. If durable cache publication fails, this
/// in-memory ownership remains valid for the current session but cannot protect cleanup after a
/// process restart.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct BuildScriptSession {
    outputs: BTreeMap<FileKey, Vec<u8>>,
}

impl BuildScriptSession {
    /// Construct an empty session.
    pub const fn new() -> Self {
        Self {
            outputs: BTreeMap::new(),
        }
    }

    /// Keys known to have been published through this session, in key order.
    #[cfg(all(test, feature = "build-script"))]
    fn known_outputs(&self) -> impl ExactSizeIterator<Item = &FileKey> {
        self.outputs.keys()
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct BuildScriptStateWire {
    state_version: u32,
    api_version: u32,
    cache_scope: Option<String>,
    script_path: String,
    fingerprint: String,
    fingerprint_inputs: FingerprintInputsWire,
    outputs: Vec<OutputArtifactWire>,
    task_plan: TaskPlan,
    generated_sources: Vec<String>,
    additional_classpath: Vec<String>,
    javac_args: Vec<String>,
    jvm_args: Vec<String>,
    compile_env: BTreeMap<String, String>,
    run_env: BTreeMap<String, String>,
    rerun_files: Vec<String>,
    rerun_env: Vec<String>,
    diagnostics: Vec<DiagnosticWire>,
    metadata: BTreeMap<String, String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct FingerprintInputsWire {
    state_version: u32,
    api_version: u32,
    cache_scope: Option<String>,
    script_path: String,
    script_digest: String,
    manifest_digest: Option<String>,
    limits: BuildScriptLimitsWire,
    files_mode: FingerprintFilesModeWire,
    files: Vec<FileFingerprintWire>,
    environment: Vec<EnvironmentFingerprintWire>,
    /// This project's resolved build features, sorted. An always-present fingerprint input — unlike
    /// `environment`, which records only `rerun_if_env_changed` names — so a changed selection
    /// deterministically rebuilds even though the script never declared it as an input. For the root
    /// that is a changed `--features`; for a dependency, a changed `[dependencies] features` list.
    features: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
enum FingerprintFilesModeWire {
    AllProjectFiles,
    Declared,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct FileFingerprintWire {
    path: String,
    digest: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct EnvironmentFingerprintWire {
    name: String,
    value_digest: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
#[allow(clippy::struct_field_names)]
struct BuildScriptLimitsWire {
    max_script_size: usize,
    max_operations: u64,
    max_string_size: usize,
    max_array_size: usize,
    max_map_size: usize,
    max_path_bytes: usize,
    max_path_depth: usize,
    max_host_directive_bytes: usize,
    max_output_files: usize,
    max_output_file_size: usize,
    max_total_output_size: usize,
    max_cache_state_size: usize,
    max_tasks: usize,
    max_task_edges: usize,
    max_task_literal_bytes: usize,
    max_task_terminals: usize,
    max_publication_roots: usize,
    max_fetch_bytes: u64,
}

impl From<&BuildScriptLimits> for BuildScriptLimitsWire {
    fn from(limits: &BuildScriptLimits) -> Self {
        Self {
            max_script_size: limits.max_script_size,
            max_operations: limits.max_operations,
            max_string_size: limits.max_string_size,
            max_array_size: limits.max_array_size,
            max_map_size: limits.max_map_size,
            max_path_bytes: limits.max_path_bytes,
            max_path_depth: limits.max_path_depth,
            max_host_directive_bytes: limits.max_host_directive_bytes,
            max_output_files: limits.max_output_files,
            max_output_file_size: limits.max_output_file_size,
            max_total_output_size: limits.max_total_output_size,
            max_cache_state_size: limits.max_cache_state_size,
            max_tasks: limits.max_tasks,
            max_task_edges: limits.max_task_edges,
            max_task_literal_bytes: limits.max_task_literal_bytes,
            max_task_terminals: limits.max_task_terminals,
            max_publication_roots: limits.max_publication_roots,
            max_fetch_bytes: limits.max_fetch_bytes,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
